contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // one public function with an input so property is quantified
    function run(bool unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // unused parameter ensures quantification over inputs
        // record balances before the call
        uint beforeOwner = address(this).balance;
        uint beforeC = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: if the owner call did not revert then C's balance is zero and
        // this contract's balance is at least its prior balance.
        assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeOwner));
    }
    receive() external payable {}
}

